def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def read_whole(path,expected):
    path=Path(path).resolve()
    raw=path.read_bytes()
    if digest(raw)!=expected["sha256"] or (
            "bytes" in expected and len(raw)!=expected["bytes"]):
        raise ValueError("Complete source/parameter identity changed: "+str(path))
    return raw


def module_nodes(source):
    tree=ast.parse(source)
    return {node.name:node for node in tree.body
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))}


def ast_dump(node):
    return ast.dump(node,include_attributes=False)


def exact_edits(source,operations,*,reverse=False):
    edits=list(reversed(operations)) if reverse else list(operations)
    for item in edits:
        before,after=(item["new"],item["old"]) if reverse else (item["old"],item["new"])
        if not before or source.count(before)!=item["count"]:
            raise ValueError("An exact complete-source edit occurrence changed")
        source=source.replace(before,after)
    return source


def validate_ready(parent,output):
    if parent.get("executed") is not False or output.get("executed") is not False:
        raise ValueError("A source plan is not an executed field")
    if len(parent["steps"])!=2 or len(output["steps"])!=2:
        raise ValueError("Both complete original moment steps are required")
    for i,(old,new) in enumerate(zip(parent["steps"],output["steps"])):
        expected=[v.replace("run09","run10") for v in old["args"]]
        if i==1:
            expected+=["--closed-phase-report",
                "{work}/run10-complete-closed-phase-grip-v1/report.json"]
        if new["args"]!=expected:
            raise ValueError("A full original numerical parameter or argument was changed")
        old_summary=next(iter(old["summary"].values()))
        new_summary=next(iter(new["summary"].values()))
        if any(new_summary.get(key)!=value for key,value in old_summary.items()):
            raise ValueError("An original complete scalar selector was dropped or changed")
        if len(old_summary)!=(33,47)[i]:
            raise ValueError("The recorded original selector inventory changed")
        for key in ("outputs","parent_bundle"):
            old_value=old[key]
            expected=([v.replace("run09","run10") for v in old_value]
                if isinstance(old_value,list) else old_value.replace("run09","run10"))
            if new[key]!=expected:
                raise ValueError("The full declared output or actual parent bundle changed")
    if output["current_reference_tail_leaves"]!=2218:
        raise ValueError("Use the true run10 reference input, not historical address leaves")
    if output["historical_address_restoration_leaves"]!=2397:
        raise ValueError("The historical carrier reconstruction remains a distinct scope")
    if output["complete_scientific_runtime_role_count"]!=75:
        raise ValueError("Keep all actual scientific source roles")
    for key in ("actual_future_report_sha256","actual_future_snapshot_identity_sha256",
            "actual_future_closed_phase_main_report_sha256"):
        if output.get(key) is not None:
            raise ValueError("Do not fabricate a future field or evidence identity")
    return dict(original_producer_arguments_preserved=10,
        original_consumer_arguments_preserved=6,
        new_consumer_closed_main_arguments=2,
        original_summary_fields_preserved=[33,47],
        complete_step_argument_counts=[len(v["args"]) for v in output["steps"]],
        complete_summary_field_counts=[
            sum(len(v) for v in step["summary"].values()) for step in output["steps"]])


